sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float stops;
uniform float offset;
uniform float gamma;
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    float a = c.a;
    if (a <= 0.0) return half4(0.0);
    half3 rgb = c.rgb / a;
    rgb = pow(max(rgb + offset, half3(0.0)), half3(1.0 / gamma)) * pow(2.0, stops);
    rgb = clamp(rgb, 0.0, 1.0);
    return half4(rgb * a, a);
}
